using FMODUnity;
using LittleLeo;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DesecratorBlobCustomAnimationData", menuName = "Data/Animation/DesecratorBlobCustomAnimationData")]
public class DesecratorBlobCustomAnimationData : CustomAnimationData
{
	[SerializeField]
	private EventReference bubbleInflatingSFX;

	[SerializeField]
	private GameObject instabilityInVFX;

	[SerializeField]
	private float delayToPlayAnimation = 0.5f;

	public override void OnReceiveCorruption(SpriteControl spriteControl, CorruptionStats corruptionStats, AnimationData animationData)
	{
		float overCorruptionPercentage = (corruptionStats as CorruptedAnimalCorruptionStats).GetOverCorruptionPercentage();
		if (overCorruptionPercentage >= 0.25f && overCorruptionPercentage < 0.5f)
		{
			if (!spriteControl.IsAnimationPlaying(AnimationType.IdleQuarterHP))
			{
				InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, delayToPlayAnimation, delegate
				{
					ReferenceSingleton<SFXHandler>.Instance.PlaySFX(bubbleInflatingSFX);
					spriteControl.PlayAnimationForced(AnimationType.IdleQuarterHP, AnimationChangeType.StayInTheNewAnimationLooping);
				});
			}
		}
		else if (overCorruptionPercentage >= 0.5f && overCorruptionPercentage < 0.75f)
		{
			if (!spriteControl.IsAnimationPlaying(AnimationType.IdleHalfHP))
			{
				InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, delayToPlayAnimation, delegate
				{
					ReferenceSingleton<SFXHandler>.Instance.PlaySFX(bubbleInflatingSFX);
					spriteControl.PlayAnimationForced(AnimationType.IdleHalfHP, AnimationChangeType.StayInTheNewAnimationLooping);
				});
			}
		}
		else if (overCorruptionPercentage >= 0.75f && overCorruptionPercentage <= 1f && !spriteControl.IsAnimationPlaying(AnimationType.IdleAlmostDead))
		{
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, delayToPlayAnimation, delegate
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(bubbleInflatingSFX);
				spriteControl.PlayAnimationForced(AnimationType.IdleAlmostDead, AnimationChangeType.StayInTheNewAnimationLooping);
			});
		}
	}

	public override AnimationType GetCustomOvercorruptAnimationType(SpriteControl spriteControl, EnemySFXData enemySFXData)
	{
		if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled())
		{
			ReferenceSingleton<VFXHandler>.Instance.GetVFX(instabilityInVFX, spriteControl.transform.position.SetZ(80f), 5f);
		}
		return AnimationType.Die;
	}
}
